func TestSelectCommands(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name         string
		cfg          Config
		wantCommands []string
		wantPhase    string
		wantErr      string
	}{
		{
			name:         "explicit command",
			cfg:          Config{Command: "echo ok", Phase: "pre-tag"},
			wantCommands: []string{"echo ok"},
			wantPhase:    "pre-tag",
		},
		{
			name:         "release commands preserve lifecycle order",
			cfg:          Config{PublishCmd: "publish", SuccessCmd: "notify", Phase: "release"},
			wantCommands: []string{"publish", "notify"},
			wantPhase:    "release",
		},
		{
			name:    "ambiguous inferred phase",
			cfg:     Config{VerifyConditionsCmd: "verify", PrepareCmd: "prepare"},
			wantErr: "multiple lifecycle phases are configured; set SEMREL_PLUGIN_PHASE or use SEMREL_PLUGIN_CMD",
		},
		{
			name:    "unsupported analyzer",
			cfg:     Config{AnalyzeCommitsCmd: "analyze"},
			wantErr: "analyzeCommitsCmd is unsupported because semrel has no external analyzer plugin phase",
		},
		{
			name:    "missing phase command",
			cfg:     Config{PrepareCmd: "prepare", Phase: "condition"},
			wantErr: `no command configured for phase "condition"`,
		},
	}

	for _, tt := range tests {
		tt := tt
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			commands, phase, err := selectCommands(tt.cfg)
			if tt.wantErr != "" {
				require.EqualError(t, err, tt.wantErr)
				return
			}
			require.NoError(t, err)
			require.Equal(t, tt.wantCommands, commands)
			require.Equal(t, tt.wantPhase, phase)
		})
	}
}

func TestExecuteUsesEnvironmentWorkingDirectoryAndTemplates(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX shell assertion")
	}
	t.Parallel()
	root := t.TempDir()
	var stdout bytes.Buffer
	var stderr bytes.Buffer

	err := Execute(context.Background(), Config{
		Command:          `printf '%s|%s|%s' "$PWD" "$CUSTOM" ${nextRelease.version}`,
		WorkingDirectory: root,
		Environment:      map[string]string{"CUSTOM": "value"},
		Timeout:          time.Second,
		Template:         TemplateData{NextVersion: "3.1.4"},
	}, &stdout, &stderr)

	require.NoError(t, err)
	require.Equal(t, root+"|value|3.1.4", stdout.String())
	require.Empty(t, stderr.String())
}

