func TestParseEnvironment(t *testing.T) {
	t.Parallel()

	environment, err := ParseEnvironment("FOO: bar\nNUMBER: \"42\"\n")
	require.NoError(t, err)
	require.Equal(t, map[string]string{"FOO": "bar", "NUMBER": "42"}, environment)

	_, err = ParseEnvironment(`{"BAD=NAME":"value"}`)
	require.EqualError(t, err, `SEMREL_PLUGIN_ENV contains invalid variable name "BAD=NAME"`)
}

func TestExecuteRejectsNonDirectoryCWD(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX shell assertion")
	}
	t.Parallel()
	path := filepath.Join(t.TempDir(), "file")
	require.NoError(t, os.WriteFile(path, []byte("x"), 0o644))

	err := Execute(context.Background(), Config{
		Command:          "true",
		WorkingDirectory: path,
	}, &bytes.Buffer{}, &bytes.Buffer{})
	require.EqualError(t, err, `configured command failed: working directory "`+path+`" is not a directory`)
}
